// === Tab: mySketch ===
const RE = Math.random()+0.5-2;

// noprotect

let Shader;
function preload(){
	Shader=new p5.Shader(this._renderer,`
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`,`
		precision highp float;
		varying vec2 vTexCoord;
		uniform highp float w;
		uniform float mx,my;
		vec2 center=vec2(${RE},0);
		uniform bool mp;
		const highp float WIDTH=${windowWidth}.;
		var highp float HEIGHT=${windowHeight}.;
		void main() {
			float x=vTexCoord.x*WIDTH;
			float y=HEIGHT-vTexCoord.y*HEIGHT;
			float WH = WIDTH/HEIGHT*4.;
			highp vec2 c = vec2((x-HEIGHT/2.)/HEIGHT*4.,(y-HEIGHT/2.)/HEIGHT*4.)+center;
			highp vec2 z = vec2(c);
			bool bd = true;
			for (int i=0;i<1296;i+=1) {
				z = vec2((z.x*z.x+(abs(z.y)*z.y)),-2.*(abs(z.x+w)+w)*z.y)+c;
				if (z.x+z.x+z.y+z.y>60.) {
					bd = false;
					gl_FragColor=vec4(float(i)/1296.,float(i)/36.,float(i)/216.,1.);
					break;
				}
			}
			if (bd) gl_FragColor=vec4(9.,8.,4.,1.);
		}
	`);
}
function setup() {
	pixelDensity(1);
  createCanvas(windowHeight*4/3, windowHeight, WEBGL);
  noStroke();
}
function draw() {
  shader(Shader);
	Shader.setUniform("w",sin(frameCount*0.5)*3+3);
	Shader.setUniform("mx",(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))));
	Shader.setUniform("my",(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	Shader.setUniform("mp",((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)));
  rect(0,0,width,height);
}

function mouseClicked(){
   save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg"); 
}

